CREATE TABLE mytable (
   Row_ID        VARCHAR(50) NOT NULL 
  ,Order_ID      VARCHAR(50) NOT NULL
  ,Order_Date    VARCHAR(50) NOT NULL
  ,Ship_Date     VARCHAR(50) NOT NULL
  ,Ship_Mode     VARCHAR(50) NOT NULL
  ,Customer_ID   VARCHAR(50) NOT NULL
  ,Customer_Name VARCHAR(50) NOT NULL
  ,Segment       VARCHAR(50) NOT NULL
  ,Country       VARCHAR(50) NOT NULL
  ,City          VARCHAR(50) NOT NULL
  ,State         VARCHAR(50) NOT NULL
  ,Postal_Code   VARCHAR(50) NOT NULL
  ,Region        VARCHAR(50) NOT NULL
  ,Product_ID    VARCHAR(50) NOT NULL
  ,Category      VARCHAR(50) NOT NULL
  ,`Sub-Category`  VARCHAR(50) NOT NULL
  ,Product_Name  VARCHAR(150) NOT NULL
  ,Sales         DECIMAL(10,4) NOT NULL
  ,Quantity      INT NOT NULL
  ,Discount      DECIMAL(5,2) NOT NULL
  ,Profit        DECIMAL(10,4) NOT NULL
);






--  Fact & Dim tables

-- 1. Customer Dim Table
CREATE TABLE dim_customer (
    customer_id VARCHAR(50) PRIMARY KEY,
    customer_name VARCHAR(100),
    segment VARCHAR(50)
);

SELECT DISTINCT 
    Customer_ID, 
    Customer_Name, 
    Segment
FROM mytable;

-- 2. Product Dim Table
CREATE TABLE dim_product (
    product_id VARCHAR(50) PRIMARY KEY,
    product_name VARCHAR(255),
    category VARCHAR(50),
    sub_category VARCHAR(50)
);

SELECT DISTINCT 
    Product_ID, 
    Product_Name, 
    Category, 
    `Sub-Category`
FROM mytable;

-- 3. Location Dim Table
CREATE TABLE dim_location (
    location_id INT AUTO_INCREMENT PRIMARY KEY,
    country VARCHAR(50),
    state VARCHAR(50),
    city VARCHAR(50),
    postal_code VARCHAR(20),
    region VARCHAR(50)
);

SELECT DISTINCT 
    Country, 
    State, 
    City, 
    Postal_Code, 
    Region
FROM mytable;

-- 4. Date Dim Table
CREATE TABLE dim_date (
    date_id INT PRIMARY KEY,
    full_date DATE,
    month INT,
    month_name VARCHAR(15),
    quarter INT,
    year INT
);

SELECT DISTINCT
    (YEAR(STR_TO_DATE(raw_date, '%m/%d/%Y')) * 10000) + 
    (MONTH(STR_TO_DATE(raw_date, '%m/%d/%Y')) * 100) + 
     DAY(STR_TO_DATE(raw_date, '%m/%d/%Y')) AS date_id,
    STR_TO_DATE(raw_date, '%m/%d/%Y') AS full_date,
    MONTH(STR_TO_DATE(raw_date, '%m/%d/%Y')) AS month,
    MONTHNAME(STR_TO_DATE(raw_date, '%m/%d/%Y')) AS month_name,
    QUARTER(STR_TO_DATE(raw_date, '%m/%d/%Y')) AS quarter,
    YEAR(STR_TO_DATE(raw_date, '%m/%d/%Y')) AS year
FROM (
    SELECT Order_Date AS raw_date FROM mytable
    UNION
    SELECT Ship_Date AS raw_date FROM mytable
) dates
ON DUPLICATE KEY UPDATE date_id = date_id;

-- 5. Sales Fact Table
CREATE TABLE fact_sales (
    fact_id INT AUTO_INCREMENT PRIMARY KEY,
    row_id VARCHAR(50),
    order_id VARCHAR(50),
    customer_id VARCHAR(50),
    product_id VARCHAR(50),
    location_id INT,
    order_date_id INT,
    ship_date_id INT,
    ship_mode VARCHAR(50),
    sales DECIMAL(10,2),
    quantity INT,
    discount DECIMAL(4,2),
    profit DECIMAL(10,2),
    FOREIGN KEY (customer_id) REFERENCES dim_customer(customer_id),
    FOREIGN KEY (product_id) REFERENCES dim_product(product_id),
    FOREIGN KEY (location_id) REFERENCES dim_location(location_id),
    FOREIGN KEY (order_date_id) REFERENCES dim_date(date_id),
    FOREIGN KEY (ship_date_id) REFERENCES dim_date(date_id)
);


    row_id, 
    order_id, 
    customer_id, 
    product_id, 
    location_id, 
    order_date_id, 
    ship_date_id, 
    ship_mode, 
    sales, 
    quantity, 
    discount, 
    profit
)
SELECT 
    m.Row_ID,
    m.Order_ID,
    m.Customer_ID,
    m.Product_ID,
    l.location_id,
    CAST(DATE_FORMAT(STR_TO_DATE(m.Order_Date, '%m/%d/%Y'), '%Y%m%d') AS UNSIGNED) AS order_date_id,
    CAST(DATE_FORMAT(STR_TO_DATE(m.Ship_Date, '%m/%d/%Y'), '%Y%m%d') AS UNSIGNED) AS ship_date_id,
    m.Ship_Mode,
    m.Sales,
    m.Quantity,
    m.Discount,
    m.Profit
FROM mytable m
JOIN dim_location l 
    ON m.Country = l.country 
   AND m.State = l.state 
   AND m.City = l.city 
   AND m.Postal_Code = l.postal_code 
   AND m.Region = l.region;


-- SQL Views & Stored Procedures

-- Monthly KPI Aggregations View
CREATE VIEW vw_monthly_kpis AS
SELECT 
    d.year,
    d.month,
    d.month_name,
    COUNT(DISTINCT f.order_id) AS total_orders,
    SUM(f.sales) AS total_revenue,
    SUM(f.profit) AS total_profit,
    AVG(f.discount) * 100 AS avg_discount_pct
FROM fact_sales f
JOIN dim_date d ON f.order_date_id = d.date_id
GROUP BY d.year, d.month, d.month_name;

-- Stored Procedure: KPI Analysis by Date Range
DELIMITER //
CREATE PROCEDURE sp_kpi_by_date_range(
    IN start_date DATE,
    IN end_date DATE
)
BEGIN
    SELECT 
        p.category,
        COUNT(DISTINCT f.order_id) AS total_orders,
        SUM(f.sales) AS total_sales,
        SUM(f.profit) AS total_profit,
        ROUND((SUM(f.profit) / NULLIF(SUM(f.sales), 0)) * 100, 2) AS profit_margin_pct
    FROM fact_sales f
    JOIN dim_product p ON f.product_id = p.product_id
    JOIN dim_date d ON f.order_date_id = d.date_id
    WHERE d.full_date BETWEEN start_date AND end_date
    GROUP BY p.category;
END //
DELIMITER ;



--  Analytical Reports

-- Report 1: Profitability Analysis Report (CTE 1)
CREATE VIEW  Profitability_Analysis_Report AS
WITH RegionalProfitability AS (
    SELECT 
        l.region,
        p.category,
        p.sub_category,
        SUM(f.sales) AS total_sales,
        SUM(f.profit) AS total_profit
    FROM fact_sales f
    JOIN dim_product p ON f.product_id = p.product_id
    JOIN dim_location l ON f.location_id = l.location_id
    GROUP BY l.region, p.category, p.sub_category
)
SELECT 
    region,
    category,
    sub_category,
    ROUND(total_sales, 2) AS total_sales,
    ROUND(total_profit, 2) AS total_profit,
    CASE 
        WHEN total_profit < 0 THEN 'Unprofitable Line'
        WHEN (total_profit / NULLIF(total_sales, 0)) < 0.15 THEN 'Low Margin'
        ELSE 'High Margin'
    END AS profitability_status
FROM RegionalProfitability
ORDER BY total_profit ASC;

-- Report 2: Customer Behavior & Loyalty Tier Report (CTE 2)
CREATE VIEW  Customer_Behavior_and_Loyalty_Tier_Report AS
WITH CustomerRFM AS (
    SELECT 
        c.customer_id,
        c.customer_name,
        c.segment,
        COUNT(DISTINCT f.order_id) AS total_orders,
        SUM(f.sales) AS lifetime_sales,
        SUM(f.profit) AS lifetime_profit
    FROM fact_sales f
    JOIN dim_customer c ON f.customer_id = c.customer_id
    GROUP BY c.customer_id, c.customer_name, c.segment
)
SELECT 
    customer_name,
    segment,
    total_orders,
    ROUND(lifetime_sales, 2) AS lifetime_sales,
    ROUND(lifetime_profit, 2) AS lifetime_profit,
    CASE 
        WHEN total_orders >= 5 AND lifetime_sales >= 3000 THEN 'VIP Tier'
        WHEN total_orders BETWEEN 2 AND 4 THEN 'Repeat Tier'
        ELSE 'One-Time Tier'
    END AS customer_tier
FROM CustomerRFM
ORDER BY lifetime_sales DESC;


-- Report 3: Sales Trends & Month-overMonth Growth Report (CTE3)
CREATE VIEW  Sales_Trends_and_Month_over_Month_Growth_Report AS
WITH MonthlyKPIs AS (
    SELECT 
        d.year,
        d.month,
        d.month_name,
        COUNT(DISTINCT f.order_id) AS total_orders,
        SUM(f.sales) AS total_revenue,
        SUM(f.profit) AS total_profit
    FROM fact_sales f
    JOIN dim_date d ON f.order_date_id = d.date_id
    GROUP BY d.year, d.month, d.month_name
)
SELECT 
    year,
    month_name,
    total_orders,
    ROUND(total_revenue, 2) AS revenue,
    ROUND(total_profit, 2) AS profit,
    ROUND(LAG(total_revenue) OVER (ORDER BY year, month), 2) AS prior_month_revenue,
    ROUND(
        ((total_revenue - LAG(total_revenue) OVER (ORDER BY year, month)) 
        / NULLIF(LAG(total_revenue) OVER (ORDER BY year, month), 0)) * 100, 2
    ) AS mom_growth_pct
FROM MonthlyKPIs
ORDER BY year, month;



--  Advanced Query Suite (15 Queries)

--  1: High Discount Impact 
SELECT p.category, SUM(f.sales) AS sales, SUM(f.profit) AS profit
FROM fact_sales f
JOIN dim_product p ON f.product_id = p.product_id
WHERE f.discount > 0.20
GROUP BY p.category;

-- 2: Unprofitable Sub-Categories 
SELECT p.sub_category, SUM(f.profit) AS total_profit
FROM fact_sales f
JOIN dim_product p ON f.product_id = p.product_id
GROUP BY p.sub_category
HAVING total_profit < 0;

--  3: Regional Margin Breakdown 
SELECT 
    l.region, 
    SUM(f.sales) AS sales, 
    SUM(f.profit) AS profit,
    CASE WHEN 
    SUM(f.profit) > 0 
    THEN 'Gain' 
    ELSE 'Loss' 
    END AS financial_status
FROM fact_sales f
JOIN dim_location l ON f.location_id = l.location_id
GROUP BY l.region;

--  4: Average Shipping Speed by Shipping Mode 
SELECT f.ship_mode, AVG(DATEDIFF(d_ship.full_date, d_order.full_date)) AS avg_shipping_days
FROM fact_sales f
JOIN dim_date d_order ON f.order_date_id = d_order.date_id
JOIN dim_date d_ship ON f.ship_date_id = d_ship.date_id
GROUP BY f.ship_mode;

--  5: Top 10 Spending Customers 
SELECT c.customer_name, SUM(f.sales) AS total_spent
FROM fact_sales f
JOIN dim_customer c ON f.customer_id = c.customer_id
GROUP BY c.customer_name
ORDER BY total_spent DESC
LIMIT 10;

--  6: Revenue Share by Customer Segment 
SELECT c.segment, SUM(f.sales) AS total_sales
FROM fact_sales f
JOIN dim_customer c ON f.customer_id = c.customer_id
GROUP BY c.segment;


--   7: Product Sales Above Average Product Sales
SELECT p.product_name, SUM(f.sales) AS total_sales
FROM fact_sales f
JOIN dim_product p ON f.product_id = p.product_id
GROUP BY p.product_name
HAVING total_sales > (
    SELECT AVG(product_total) 
    FROM (
        SELECT SUM(sales) AS product_total 
        FROM fact_sales 
        GROUP BY product_id
    ) sub
);

--  8: Consumer Segment Top Spender 
SELECT c.customer_name, SUM(f.sales) AS total_sales
FROM fact_sales f
JOIN dim_customer c ON f.customer_id = c.customer_id
WHERE c.segment = 'Consumer'
GROUP BY c.customer_name
ORDER BY total_sales DESC
LIMIT 1;

--  9: Yearly Trend Aggregation 
SELECT d.year, SUM(f.sales) AS total_sales, SUM(f.profit) AS total_profit
FROM fact_sales f
JOIN dim_date d ON f.order_date_id = d.date_id
GROUP BY d.year
ORDER BY d.year;

--  10: Most Popular Product Category by Quantity 
SELECT p.category, SUM(f.quantity) AS total_units_sold
FROM fact_sales f
JOIN dim_product p ON f.product_id = p.product_id
GROUP BY p.category
ORDER BY total_units_sold DESC;

--  11: Products Sold in Multiple Regions 
SELECT p.product_name, COUNT(DISTINCT l.region) AS region_count
FROM fact_sales f
JOIN dim_product p ON f.product_id = p.product_id
JOIN dim_location l ON f.location_id = l.location_id
GROUP BY p.product_name
HAVING region_count > 1;

--  12: Cross-Selling Market Basket Identification 
SELECT f1.product_id AS product_1, f2.product_id AS product_2, COUNT(*) AS times_bought_together
FROM fact_sales f1
JOIN fact_sales f2 ON f1.order_id = f2.order_id AND f1.product_id < f2.product_id
GROUP BY f1.product_id, f2.product_id
ORDER BY times_bought_together DESC
LIMIT 5;

--  13: Bottom 5 States by Net Profit 
SELECT l.state, SUM(f.profit) AS total_profit
FROM fact_sales f
JOIN dim_location l ON f.location_id = l.location_id
GROUP BY l.state
ORDER BY total_profit ASC
LIMIT 5;

-- 14: Quarterly Financial Summary 
SELECT d.year, d.quarter, SUM(f.sales) AS sales, SUM(f.profit) AS profit
FROM fact_sales f
JOIN dim_date d ON f.order_date_id = d.date_id
GROUP BY d.year, d.quarter
ORDER BY d.year, d.quarter;

--  15: Orders Flagged for Loss Mitigation 
SELECT order_id, sales, profit,
    CASE 
        WHEN profit < -100 
        THEN 'Critical Loss'
        ELSE 'Minor Loss'
    END AS loss_severity
FROM fact_sales
WHERE profit < 0
ORDER BY profit ASC;